import { assert } from 'chai'
import { describe, it } from 'mocha'
import * as dist from '../src/dist'

// Hand-written, NOT generated by scripts/precision-refs-continuous.py (issues #1250, #1302, #1318).
//
// NoncentralT.fnm(nu, mu, x) computes the noncentral-t CDF and rounds to exactly 1 (or 0)
// whenever the true survival is closer to the boundary than Number.EPSILON allows a double
// to distinguish it from 1 (or 0) -- this is not a precision bug fnm itself can fix (no double
// can represent a value that close to 1), so NoncentralT.snm(nu, mu, x) was added as a direct
// survival sibling (mp.dps=50 mpmath quadrature reference below), mirroring how
// InverseGaussian.survival()/marcumP already exist alongside their primary CDF-style methods
// elsewhere in this codebase. See the #1250 solution doc for the full derivation. #1302
// confirmed the identical failure directly on NoncentralT._pdf's own fnm difference (not just
// DoublyNoncentralT._pdfPoissonMixture's), but its fallback (a NoncentralT._fnmDiff helper porting
// #1250's nu>=30-gated snm fallback) only caught the large-nu case: #1318 found a second,
// independent blind spot below that gate (both fnm calls stuck bit-for-bit at phi, never
// separating, so the raw difference never reaches the >=30/1e-9 magnitude check at all) at low nu
// -- and found NoncentralT.snm's own tanh-sinh domain (tuned only for nu>=30) is not reliable
// there either. #1318 replaced _fnmDiff's CDF-differencing fallback with NoncentralT._pdfDirect, a
// direct quadrature of the density's own defining formula (a single positive integrand, no
// cancellation), gated by the corrected two-condition check inlined into _pdf itself.
// See solutions/correctness/2026-08-02-2040-noncentral-t-fnmdiff-saturation-fix.md
//
// This lives outside test/precision-continuous.js's generated REFS array because
// NoncentralT.fnm/.snm are `@ignore`d static helpers, not `new dist.X(...).pdf()/.cdf()`
// instance methods the generated runner's { name, params, points } shape assumes. It also covers
// DoublyNoncentralT(5, 5, 120)'s own reported point (x = -0.7, issue #1250) directly on
// pdf/cdf rather than folding it into the existing [5, 5, 120] precision-gate group, since that
// group is regenerated wholesale by scripts/precision-refs-continuous.py and this point's own
// tolerances (see below) were derived by hand, not by that script.
describe('NoncentralT/DoublyNoncentralT near-CDF-boundary precision (#1250, #1302, #1318)', () => {
  it('NoncentralT.fnm saturates to exactly 1 at the reported regime (documents the unfixable-in-fnm-itself IEEE754 floor)', () => {
    // nu0 = nu + 2i for i in the Poisson(60) weight's significant range (~50-70) that
    // DoublyNoncentralT(5, 5, 120)._pdfPoissonMixture evaluates at x = -0.7; the true survival
    // there is far below Number.EPSILON, so fnm cannot represent it -- this is expected,
    // permanent behavior, not something #1250 changes.
    assert.strictEqual(dist.NoncentralT.fnm(125, -5, 3.5), 1)
  })

  it('NoncentralT.snm distinguishes that same near-1 CDF to ~1e-13 relative error (mpmath mp.dps=50)', () => {
    // mpmath mp.dps=50: 1 - nct_cdf(125, -5, 3.5) -> 5.209881454913731e-17 (scripts/precision-refs-continuous.py's nct_cdf)
    const ref = 5.209881454913731e-17
    assert.approximately(dist.NoncentralT.snm(125, -5, 3.5) / ref, 1, 1e-11)
  })

  it('DoublyNoncentralT(5, 5, 120).pdf(-0.7) matches mpmath to ~1e-13 (was ~1.7x off before #1250)', () => {
    // mpmath mp.dps=50: dnct_pdf(5, 5, 120, -0.7) -> 8.082662965607937e-15 (scripts/precision-refs-continuous.py's dnct_pdf,
    // independently re-derived Poisson(theta/2) mixture of nct_pdf, not read off ranjs)
    // Measured relative error after the fix is ~1.15e-14; 1e-13 keeps a ~9x margin.
    const ref = 8.082662965607937e-15
    const d = new dist.DoublyNoncentralT(5, 5, 120)
    assert.approximately(d.pdf(-0.7) / ref, 1, 1e-13)
  })

  it('DoublyNoncentralT(5, 5, 120).cdf(-0.7) matches mpmath (same fnm-saturation root cause as pdf above, found while validating #1250)', () => {
    // mpmath mp.dps=50: dnct_cdf(5, 5, 120, -0.7) -> 2.624860485053668e-16 (rounded to the nearest
    // double; full mpmath precision is 2.6248604850536683306...e-16), independently re-derived
    // (not read off ranjs) as the Poisson(theta/2) mixture of nct_cdf, matching
    // scripts/precision-refs-continuous.py's dnct_cdf -- see
    // solutions/correctness/2026-08-01-2030-noncentral-t-fnm-snm-boundary-saturation.md
    // Measured relative error after the fix is ~9.6e-11; 1e-9 keeps a ~10x margin.
    const ref = 2.624860485053668e-16
    const d = new dist.DoublyNoncentralT(5, 5, 120)
    assert.approximately(d.cdf(-0.7) / ref, 1, 1e-9)
  })

  it('NoncentralT(30, 5).pdf(40) matches mpmath (issue #1302: the same fnm-difference saturation directly on NoncentralT._pdf, independent of DoublyNoncentralT)', () => {
    // #1250's own solution doc flagged this as unconfirmed residual scope: NoncentralT._pdf
    // computes nu * (fnm(nu+2, mu, x*nuScale) - fnm(nu, mu, x)) / x, structurally identical to
    // DoublyNoncentralT._pdfPoissonMixture's per-term difference. Confirmed here: pre-fix, both
    // fnm(32, 5, 40*nuScale) and fnm(30, 5, 40) independently saturate to exactly 1, so the raw
    // difference is exactly 0 and NoncentralT(30, 5).pdf(40) returned 0.
    // mpmath mp.dps=50: nct_pdf(30, 5, 40) -> 1.544427941483997268973453e-18 (scripts/precision-refs-continuous.py's
    // nct_pdf, rounded to float64), independently re-derived via direct chi-squared-mixture
    // quadrature, not read off ranjs. Measured relative error after the fix is ~2.7e-15.
    // As of #1318, this case is caught by _pdf's nu>=30-gated `nearOppositeBoundary` condition and
    // falls back to NoncentralT._pdfDirect (a direct quadrature of the density formula), not the
    // NoncentralT.snm-based fallback #1302 originally shipped -- the *value* asserted here is
    // unchanged, only the code path computing it.
    // See solutions/correctness/2026-08-01-2030-noncentral-t-fnm-snm-boundary-saturation.md and
    // solutions/correctness/2026-08-02-2040-noncentral-t-fnmdiff-saturation-fix.md
    const ref = 1.5444279414839973e-18
    const d = new dist.NoncentralT(30, 5)
    assert.approximately(d.pdf(40) / ref, 1, 1e-13)
  })

  it('NoncentralT(5, 6).pdf(-0.5) matches mpmath (issue #1318: a second, independent blind spot in the fnm-difference saturation guard, below the nu>=30 magnitude gate #1302 already covers)', () => {
    // #1302 (test above) fixed the case where nu is large enough (>=30) for the raw fnm difference
    // to shrink below 1e-9 while still resolved away from phi. This case is structurally different:
    // nu=5 and nu=7 (= nu+2) both stay stuck bit-for-bit at phi = 0.5*(1+erf(-mu/sqrt(2))) the whole
    // time (never separate from it), so the raw difference is exactly 0 without ever tripping a
    // nu>=30-gated magnitude check. Confirmed pre-fix: both fnm(7, 6, -0.5*nuScale) and
    // fnm(5, 6, -0.5) return the bit-identical 9.865877004244794e-10 = phi to 1 part in 2e7.
    // mpmath mp.dps=50 reference (independently re-derived via the chi-squared-mixture density
    // integral f(t) = int_0^inf s*phi(s*t-mu)*chi2_pdf(v;nu) dv, s=sqrt(v/nu) -- a different
    // parameterization than nct_pdf's own y-integral formula, not read off ranjs):
    // nct_pdf(5, 6, -0.5) -> 3.3376919669494116e-10
    const ref = 3.3376919669494116e-10
    const d = new dist.NoncentralT(5, 6)
    assert.approximately(d.pdf(-0.5) / ref, 1, 1e-13)
  })

  it('NoncentralT(1, 8).pdf(-0.3) matches mpmath (issue #1318: the same stuck-at-phi blind spot at the lowest valid nu)', () => {
    // mpmath mp.dps=50 reference (same independent chi-squared-mixture formula as above):
    // nct_pdf(1, 8, -0.3) -> 4.784102889962413e-16
    const ref = 4.784102889962413e-16
    const d = new dist.NoncentralT(1, 8)
    assert.approximately(d.pdf(-0.3) / ref, 1, 1e-13)
  })

  it('NoncentralT(10, 6).pdf(-1.0) matches mpmath (issue #1318: a case that was wrong-but-nonzero pre-fix, not merely zeroed -- confirms the guard is not just an exactly-zero detector)', () => {
    // Pre-fix this returned 9.843704740220005e-9, ~480x the true value -- one fnm call had
    // partially resolved off phi while the other stayed closer to it, so the raw difference was
    // small but nonzero, evading both the old nu>=30 magnitude gate (nu=10 < 30) and a naive
    // exactly-zero check.
    // mpmath mp.dps=50 reference (same independent chi-squared-mixture formula as above):
    // nct_pdf(10, 6, -1.0) -> 2.0534618407472332e-11
    const ref = 2.0534618407472332e-11
    const d = new dist.NoncentralT(10, 6)
    assert.approximately(d.pdf(-1.0) / ref, 1, 1e-13)
  })

  it('NoncentralT(8, 2).pdf(2.5) pins the _pdfDirect-fallback gate OFF for ordinary (non-saturating) parameters', () => {
    // Mirrors the DoublyNoncentralT gate-off pin below, but proves it by direct instrumentation
    // rather than by hand-deriving a and b: since NoncentralT._pdfDirect is documented (see its own
    // JSDoc) to stay accurate to ~1e-14 on saturating cases too, an assertion on the final pdf()
    // value alone cannot distinguish "fast path taken" from "gate misfired, fallback taken, and the
    // fallback happened to be equally accurate" -- so this replaces _pdfDirect with a throwing stub
    // for the duration of the call, making a misfire fail loudly instead of silently passing.
    // Reference value is test/precision-continuous.js's own generated NoncentralT([8, 2]) group at
    // x=2.5 (scripts/precision-refs-continuous.py's nct_pdf), confirming the #1318 fix does not
    // alter any ordinary (already-correct) NoncentralT.pdf() call -- now via the fast path only,
    // provably, not merely plausibly.
    const ref = 0.2939872121807985
    const originalPdfDirect = dist.NoncentralT._pdfDirect
    dist.NoncentralT._pdfDirect = () => {
      throw new Error('NoncentralT._pdfDirect fallback fired for an ordinary, non-saturating parameter set')
    }
    try {
      const d = new dist.NoncentralT(8, 2)
      assert.approximately(d.pdf(2.5) / ref, 1, 2e-14)
    } finally {
      dist.NoncentralT._pdfDirect = originalPdfDirect
    }
  })

  it('DoublyNoncentralT(5, 1, 2).pdf(-2.0)/.cdf(-2.0) pin the snm-fallback gate OFF for ordinary (non-saturating) parameters', () => {
    // #1250 tuned _fnmDiff/_cdfTerm's expensive NoncentralT.snm fallback to fire only once
    // lo.nu/nu0 >= 30 AND the raw fnm difference/complement is already < 1e-9 -- both must hold.
    // Nothing added by #1250 pins the negative case: that the gate stays OFF, and the plain
    // fnm-difference path alone still drives the result, for ordinary (small-nu, small-theta)
    // parameters where fnm has no precision problem. DoublyNoncentralT(5, 1, 2) at x = -2.0
    // reuses this file's neighboring group's own parameters, both to exercise _pdf's
    // x*mu < 0 (Poisson-mixture) branch and _cdf's x < 0 (complement) branch that _fnmDiff/
    // _cdfTerm gate, and to keep the reference values sourced from the same generated
    // mpmath mp.dps=50 pipeline as test/precision-continuous.js's DoublyNoncentralT([5, 1, 2])
    // group (scripts/precision-refs-continuous.py's dnct_pdf/dnct_cdf) rather than a fresh,
    // hand-computed value.
    //
    // Proof the gate never engages: the Poisson(theta/2) = Poisson(1) mixture weight (t.p in
    // both _pdf's and _cdf's recursiveSum loops) depends only on theta and the term index i,
    // not on nu, mu or x, so it was instrumented once for this theta = 2 and is exact for every
    // DoublyNoncentralT(nu, mu, 2) call: weight >= 1e-9 (the last "non-negligible" term by
    // _fnmDiff/_cdfTerm's own 1e-9 magnitude threshold) only through i = 11, where
    // nu0 = nu + 2*11 = 5 + 22 = 27, still below the nu0 >= 30 gate. The gate's nu0 >= 30 half
    // only turns true at i = 13 (nu0 = 31) onward, by which point the weight has already decayed
    // to ~5.9e-11 -- confirming this call cannot trip the fallback and would return the identical
    // value under the pre-#1250 code, which only ever took the plain fnm-difference path.
    const pdfRef = 0.005599439856554967
    const cdfRef = 0.003190244410576169
    const d = new dist.DoublyNoncentralT(5, 1, 2)
    assert.approximately(d.pdf(-2.0) / pdfRef, 1, 1e-12)
    assert.approximately(d.cdf(-2.0) / cdfRef, 1, 1e-12)
  })
})
